/**
 * Portfolio data — real Rogue Studio clients.
 *
 * Media comes from two places:
 *   • `reels` — local mp4s under /public/reels, with a preview loop and poster
 *     generated by the ffmpeg pass (see src/lib/reels.ts).
 *   • `bunnyMatch` — keys identifying this client's Bunny Stream uploads. The
 *     portfolio matches videos by title or description and attaches them
 *     automatically, so a new upload appears without a code change. Uploads are
 *     named after the client's Instagram handle (e.g. "averaclothing.in_178905…").
 *
 * Reels that resolve to nothing render as a "reel in the edit bay" placeholder —
 * never a broken player.
 *
 * Metrics policy: REAL numbers only, from client accounts or delivery records.
 * Where no figure exists we show qualitative `highlights` instead of inventing
 * percentages. Clients still being onboarded carry `needsContext` and roll in the
 * end credits rather than claiming a case study that hasn't happened yet.
 */

export type PortfolioTag =
  | 'Solar & Energy'
  | 'Spaces'
  | 'Fashion'
  | 'Finance'
  | 'Automotive'
  | 'In-House'

export interface Metric {
  value: string
  label: string
}

export interface PortfolioClient {
  id: string
  name: string
  slug: string
  logo: string
  /** Subtle glow / accent used behind the logo and on hover states. */
  accent: string
  industry: string
  tag: PortfolioTag
  instagram: string
  instagramHandle: string
  /** Short punchy line under the name. */
  tagline: string
  /** One-line summary of the engagement. */
  summary: string
  /** What we actually handle for them. */
  scope: string[]
  /** Longer narrative. */
  caseStudy: string
  /** REAL figures only. May be empty. */
  metrics: Metric[]
  /** Qualitative wins shown when metrics are sparse. */
  highlights: string[]
  /** Local mp4 reels (under /public/reels). */
  reels: string[]
  /**
   * Keys that identify this client's Bunny Stream videos — an upload-filename
   * prefix (usually their Instagram handle) or a Description tag. Several are
   * allowed: reposts upload under the original account's handle, and older
   * library entries are tagged by description rather than named after a handle.
   */
  bunnyMatch?: string[]
  /** Rogue's own subsidiary brand, not a paying client. */
  isInHouse?: boolean
  /** Engagement too new for a case study — rolls in the end credits instead. */
  needsContext?: boolean
}

