/* ── Resolved shapes (built in the server page after media resolution) ── */

export interface ResolvedReel {
  src: string
  available: boolean
}

export interface ResolvedClient extends Omit<PortfolioClient, 'reels'> {
  reels: ResolvedReel[]
  /** Count of reels that actually resolved to something playable. */
  liveReelCount: number
}

/** Lightbox payload. */
export interface ActiveReel {
  src: string
  client: string
  instagram: string
}
